  @Test
  public void readAllPagesReturnsEveryDataPageAndItsValueCount() throws Exception {
    Path temporaryDirectory = Files.createTempDirectory("read-all-pages-");
    Path temporaryFile = temporaryDirectory.resolve("data.parquet");
    Configuration configuration = new Configuration();

    MessageType schema = Types.buildMessage()
        .required(org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName.INT32)
        .named("value")
        .named("message");

    GroupWriteSupport.setSchema(schema, configuration);

    try {
      org.apache.hadoop.fs.Path parquetPath =
          new org.apache.hadoop.fs.Path(temporaryFile.toUri());

      try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(parquetPath)
          .withConf(configuration)
          .build()) {
        SimpleGroupFactory groupFactory = new SimpleGroupFactory(schema);
        writer.write(groupFactory.newGroup().append("value", 10));
        writer.write(groupFactory.newGroup().append("value", 20));
        writer.write(groupFactory.newGroup().append("value", 30));
      }

      try (ParquetFileReader reader = ParquetFileReader.open(configuration, parquetPath)) {
        PageReadStore rowGroup = reader.readNextRowGroup();
        assertNotNull(rowGroup);

        ColumnDescriptor column = schema.getColumns().get(0);
        PageReader pageReader = rowGroup.getPageReader(column);

        assertEquals(3L, pageReader.getTotalValueCount());

        DataPage firstPage = pageReader.readPage();
        assertNotNull(firstPage);
        assertEquals(3, firstPage.getValueCount());
        assertNull(pageReader.readPage());
        assertNull(reader.readNextRowGroup());
      }
    } finally {
      deleteRecursively(temporaryDirectory);
    }
  }

  private static void deleteRecursively(Path directory) throws IOException {
    List<Path> paths;
    try (Stream<Path> walk = Files.walk(directory)) {
      paths = walk.sorted(Comparator.reverseOrder()).toList();
    }

    for (Path path : paths) {
      Files.deleteIfExists(path);
    }
  }
}

