        List<ByteBuffer> buffers = Collections.singletonList(buffer);

        // 3. Create ChunkDescriptor using reflection
        // ChunkDescriptor(ColumnDescriptor col, ColumnChunkMetaData metadata, long fileOffset, long size)
        Class<?> parquetFileReaderClass = ParquetFileReader.class;
        Class<?> chunkDescriptorClass = null;
        for (Class<?> inner : parquetFileReaderClass.getDeclaredClasses()) {
            if (inner.getSimpleName().equals("ChunkDescriptor")) {
                chunkDescriptorClass = inner;
                break;
            }
        }
        assertNotNull(chunkDescriptorClass, "ChunkDescriptor class not found");

        // Get ColumnDescriptor from the reader's schema
        Method getColumnDescriptorMethod = parquetFileReaderClass.getDeclaredMethod(
            "getColumnDescriptor", int.class, int.class);
        getColumnDescriptorMethod.setAccessible(true);
        ColumnDescriptor colDesc = (ColumnDescriptor) getColumnDescriptorMethod.invoke(reader, rowGroupOrdinal, columnOrdinal);

        Constructor<?> descriptorConstructor = chunkDescriptorClass.getDeclaredConstructor(
            ColumnDescriptor.class, ColumnChunkMetaData.class, long.class, long.class);
        descriptorConstructor.setAccessible(true);
        Object descriptor = descriptorConstructor.newInstance(colDesc, colMeta, startOffset, length);

        // 4. Create Chunk via reflection
        // Chunk(ChunkDescriptor descriptor, List<ByteBuffer> buffers, OffsetIndex offsetIndex, long rowCount)
        Class<?> chunkClass = null;
        for (Class<?> inner : parquetFileReaderClass.getDeclaredClasses()) {
            if (inner.getSimpleName().equals("Chunk")) {
                chunkClass = inner;
                break;
            }
        }
        assertNotNull(chunkClass, "Chunk class not found");

        Constructor<?> chunkConstructor = chunkClass.getDeclaredConstructor(
            chunkDescriptorClass, List.class, OffsetIndex.class, long.class);
        chunkConstructor.setAccessible(true);
        Object chunk = chunkConstructor.newInstance(descriptor, buffers, null, 0L);

        // 5. Invoke readAllPages
        // public ColumnChunkPageReader readAllPages(BlockCipher.Decryptor headerBlockDecryptor,
        //     BlockCipher.Decryptor pageBlockDecryptor, byte[] aadPrefix,
        //     int rowGroupOrdinal, int columnOrdinal)
        BlockCipher.Decryptor headerBlockDecryptor = null;
        BlockCipher.Decryptor pageBlockDecryptor = null;
        byte[] aadPrefix = new byte[0];

        Method readAllPagesMethod = chunkClass.getDeclaredMethod(
            "readAllPages",
            BlockCipher.Decryptor.class,
            BlockCipher.Decryptor.class,
            byte[].class,
            int.class,
            int.class);
        readAllPagesMethod.setAccessible(true);
        ColumnChunkPageReader pageReader = (ColumnChunkPageReader) readAllPagesMethod.invoke(
            chunk, headerBlockDecryptor, pageBlockDecryptor, aadPrefix, rowGroupOrdinal, columnOrdinal);

        // 6. Assertions
        assertNotNull(pageReader, "PageReader should not be null");
        // Try to read a page to verify content
        DataPage page = pageReader.readPage();
        assertNotNull(page, "Should be able to read at least one page");
    }

    private long findFooterStart(FileSystem fs, Path path, long fileSize) throws IOException {
        byte[] magic = new byte[]{(byte) 'P', (byte) 'A', (byte) 'R', (byte) '1'};
        byte[] efmagic = new byte[]{(byte) 'E', (byte) 'F', (byte) 'M', (byte) 'A', (byte) 'G', (byte) 'I', (byte) 'C'};

        // Scan backwards from the end of the file
        for (long i = fileSize - 8; i >= 0; i--) {
            byte[] buf = new byte[8];
            try (var stream = fs.open(path)) {
                stream.seek(i);
                int bytesRead = 0;
                while (bytesRead < 8) {
                    int read = stream.read(buf, bytesRead, 8 - bytesRead);
                    if (read == -1) {
                        break;
                    }
                    bytesRead += read;
                }
            }

            boolean isMagic = true;
            for (int j = 0; j < 4 && j < buf.length; j++) {
                if (buf[j] != magic[j]) {
                    isMagic = false;
                    break;
                }
            }
            if (isMagic) {
                return i;
            }

            boolean isEfmagic = true;
            for (int j = 0; j < 7 && j < buf.length; j++) {
                if (buf[j] != efmagic[j]) {
                    isEfmagic = false;
                    break;
                }
            }
            if (isEfmagic) {
                return i;
            }
        }
        throw new IOException("Could not find footer magic bytes");
    }

    private byte[] readBytes(FileSystem fs, Path path, long start, long length) throws IOException {
        try (var stream = fs.open(path)) {
            stream.seek(start);
            byte[] buffer = new byte[(int) length];
            int bytesRead = 0;
            while (bytesRead < length) {
                int read = stream.read(buffer, bytesRead, (int) length - bytesRead);
                if (read == -1) {
                    break;
                }
                bytesRead += read;
            }
            if (bytesRead != length) {
                throw new IOException("Could not read all bytes");
            }
            return buffer;
        }
    }
